-- ESCO taxonomy generated by `taxonomy-pipeline import-source`; review before importing.
-- Same session settings as the client's phpMyAdmin dumps: clears NO_BACKSLASH_ESCAPES,
-- which the string escaping below relies on.
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS `esco_categories` LIKE `categories`;
CREATE TABLE IF NOT EXISTS `esco_specialities` LIKE `specialities`;
CREATE TABLE IF NOT EXISTS `esco_tags` LIKE `tags`;
CREATE TABLE IF NOT EXISTS `esco_speciality_tags` LIKE `speciality_tags`;






















































































COMMIT;
